#!/usr/bin/env bash
# PreToolUse(Write|Edit|MultiEdit|NotebookEdit) — protects generated files, secrets and
# sensitive configuration.
#   exit 2            -> block (stderr shown to Claude)
#   JSON "ask"        -> require explicit user confirmation for sensitive config changes
set -uo pipefail

input="$(cat)"
command -v jq >/dev/null 2>&1 || { echo "guard-write: jq is required (brew install jq)" >&2; exit 2; }

file="$(printf '%s' "$input" | jq -r '.tool_input.file_path // .tool_input.notebook_path // ""')"
[ -z "$file" ] && exit 0
content="$(printf '%s' "$input" | jq -r '[.tool_input.content, .tool_input.new_string, (.tool_input.edits // [] | map(.new_string) | join("\n"))] | map(select(. != null)) | join("\n")')"

project="${CLAUDE_PROJECT_DIR:-$(pwd)}"
rel="${file#"$project"/}"

block() {
	echo "BLOCKED by .claude/hooks/guard-write.sh: $1" >&2
	exit 2
}

ask() {
	jq -n --arg reason "$1" '{
		hookSpecificOutput: {
			hookEventName: "PreToolUse",
			permissionDecision: "ask",
			permissionDecisionReason: $reason
		}
	}'
	exit 0
}

# --- Secrets must never be written anywhere ---------------------------------------------------
if printf '%s' "$content" | grep -Eq '_\|WARNING:-DO-NOT-SHARE-THIS|ghp_[A-Za-z0-9]{20,}|github_pat_[A-Za-z0-9_]{20,}|sk-ant-[A-Za-z0-9-]{10,}|-----BEGIN [A-Z ]*PRIVATE KEY-----'; then
	block "the content looks like a credential (cookie/token/private key). Never commit secrets."
fi

# Files outside the project: only the secret check applies.
[ "$rel" = "$file" ] && exit 0

case "$rel" in
	# Generated or vendored — edits would be overwritten and hide the real fix.
	DevPackages/* | Packages/* | ServerPackages/*)
		block "$rel is installed by Wally. Change wally.toml and run 'make packages' instead." ;;
	build/* | sourcemap.json | .cache/*)
		block "$rel is a generated artifact. Change the sources and rebuild." ;;
	wally.lock)
		block "wally.lock is generated by 'wally install'." ;;
	.env | .env.* | *.pem | *.key)
		block "secret files must not be created or edited by agents." ;;
	src/*.lua | tests/*.lua | tools/*.lua)
		block "use the .luau extension for Luau sources." ;;
	# Sensitive configuration — allowed, but only with explicit user confirmation.
	.claude/settings.json | .claude/hooks/*)
		ask "Changing Claude Code permissions/hooks for the whole team ($rel)." ;;
	.github/workflows/*)
		ask "Changing the CI pipeline ($rel)." ;;
	rokit.toml | wally.toml)
		ask "Changing the toolchain or dependencies ($rel). Every dependency must be justified in docs/DECISIONS.md." ;;
	default.project.json | test.project.json)
		ask "Changing the Rojo project mapping ($rel)." ;;
esac

exit 0
